function enter(s: GameState, scene: SceneBuilder): void {
  const arg = s.locArg;
  switch (arg) {
    case 'get_nickname':
      enterGetNickname(s, scene);
      break;
    case 'rusMale':
      enterRusMale(s, scene);
      break;
    case 'rusFemale':
      enterRusFemale(s, scene);
      break;
    case 'rusSur':
      enterRusSur(s, scene);
      break;
    default:
      enterDefault(s, scene);
      break;
  }
}

export const npcrnamefile: LocationDef = {
  name: 'npcrnamefile',
  region: 'other',
  enter: enter,
};
